LIB.symptoms = [
  { id: 'boomy', name: 'Boomy, one-note bass', symptom: 'Certain bass notes jump out and ring; bass lines sound uneven.', causes: ['Strong axial room modes', 'Listening position at a modal peak (e.g. against the rear wall)', 'Speaker/sub in a corner exciting all modes', 'Square/cubic room or dimensions in simple ratios'], diagnose: ['Run your dimensions in the Room Analyzer — look for clustered modes', 'Play the mode frequencies (Analyzer → click a mode) and walk around', 'Measure a waterfall: long ridges = ringing modes'], fixes: ['Move the listening seat (start at 38 % of length) and speakers', 'Corner bass traps, as thick as possible', 'Tuned membrane trap for one dominant mode', 'Multiple subwoofers', 'EQ cut at the peak after physical fixes'], alternatives: ['Headphone cross-checks for bass decisions'], tools: ['analyzer', 'absorbers', 'measure'] },
  { id: 'missing-bass', name: 'Bass disappears at the seat', symptom: 'Deep notes vanish at the mix position but return when you move.', causes: ['Seat at a modal null (e.g. room centre)', 'SBIR cancellation from front/side walls or the floor', 'Phase mismatch between sub and mains'], diagnose: ['Is the seat exactly at L/2 or W/2?', 'Compute c/(4d) for each speaker–boundary distance', 'Measure with sub alone, mains alone, both'], fixes: ['Move the seat off centre', 'Change speaker distance from the front wall (or soffit-mount)', 'Flip sub polarity / adjust delay at crossover', 'Never boost a null with EQ'], alternatives: ['Multiple subs to fill nulls'], tools: ['analyzer', 'calc'] },
  { id: 'flutter', name: 'Flutter echo (zinging clap)', symptom: 'A clap produces a metallic buzzing tail.', causes: ['Parallel hard surfaces (walls, or floor–ceiling)'], diagnose: ['Clap between each pair of surfaces and listen'], fixes: ['Absorb or diffuse one surface of each parallel pair at ear height', 'Splay one wall ≥ 5–10°', 'Bookshelves, curtains or slat panels'], alternatives: ['A large rug plus a ceiling cloud for floor–ceiling flutter'], tools: ['absorbers', 'diffusers'] },
  { id: 'harsh', name: 'Harsh, bright, “splashy” room', symptom: 'Cymbals and vocals sound edgy; fatiguing.', causes: ['Too many hard surfaces; strong first reflections', 'Glass and bare drywall near speakers'], diagnose: ['Mirror trick for first reflection points', 'ETC measurement for early reflections'], fixes: ['Broadband absorption at reflection points', 'Rug, cloud, curtains over glass'], alternatives: ['Diffusion if the room is large enough'], tools: ['absorbers', 'analyzer'] },
  { id: 'dead-boomy', name: 'Dull yet boomy room', symptom: 'Highs are gone, yet bass rings and low-mids are thick.', causes: ['Thin foam or carpet everywhere (absorbs only highs)', 'No bass trapping'], diagnose: ['Room Analyzer: RT per band — long at 125/250, very short at 2–4 k'], fixes: ['Remove some thin foam; replace with thick broadband panels and bass traps', 'Add some diffusion or reflective surfaces back'], alternatives: [], tools: ['analyzer', 'absorbers'] },
  { id: 'boxy', name: 'Boxy vocal booth', symptom: 'Voice sounds like it’s in a cupboard — honky low-mids.', causes: ['Small dimensions place modes at 100–300 Hz', 'Thin foam treatment'], diagnose: ['Room Analyzer with booth dimensions — look at modes 100–300 Hz'], fixes: ['Deep (100–150 mm + gap) broadband on all surfaces', 'Make the booth bigger or taller if possible', 'Record in the larger room with gobos instead'], alternatives: ['Close-mic with a dynamic or cardioid and treat behind the singer'], tools: ['analyzer', 'absorbers'] },
  { id: 'translation', name: 'Mixes don’t translate', symptom: 'Mixes sound great in the room, wrong everywhere else.', causes: ['Room frequency response errors (modes, SBIR)', 'Asymmetry causing image problems', 'Monitoring level too low/high'], diagnose: ['Measure L and R separately at the seat', 'Check symmetry of furniture, windows and doors'], fixes: ['Fix position and bass first; add traps', 'Symmetric treatment', 'Calibrate monitoring level', 'Reference tracks and headphones'], alternatives: [], tools: ['analyzer', 'measure'] },
  { id: 'image', name: 'Vague stereo image', symptom: 'Phantom centre is wide or off-centre; panning is unclear.', causes: ['Asymmetric side reflections', 'Desk/console reflections', 'Speakers not equidistant or not toed-in'], diagnose: ['Measure distances with a tape', 'Play mono pink noise — it should be a narrow centre image'], fixes: ['Symmetrical first-reflection treatment', 'Equilateral triangle; tweeters to ears', 'Angle or raise speakers above the desk'], alternatives: [], tools: ['analyzer'] },
  { id: 'neighbours-bass', name: 'Neighbours hear the bass', symptom: 'Complaints about thumping even though mids are quiet.', causes: ['Lightweight walls/floors with low TL at 40–100 Hz', 'Structure-borne transmission from subs/kick', 'Flanking via shared floor or ceiling void'], diagnose: ['Compare dBC and dBA at the neighbour', 'Soundproofing planner: look at the 63 and 125 Hz bands'], fixes: ['Add mass + decoupling (independent wall/ceiling)', 'Decouple subs and speakers from the structure (but stands alone won’t fix airborne bass)', 'Floating floor for drums/subs'], alternatives: ['Limit bass level at night; headphones'], tools: ['isolation', 'floors'] },
  { id: 'footsteps', name: 'Footsteps from upstairs', symptom: 'Thuds and creaks from the floor above.', causes: ['Impact noise through the floor/ceiling structure'], diagnose: ['Is it louder in the middle of the ceiling?'], fixes: ['Upstairs: carpet + underlay or floating floor (best — at the source)', 'Downstairs: independent ceiling or isolation hangers + 2 layers gypsum + insulation'], alternatives: [], tools: ['isolation', 'floors'] },
  { id: 'hvac', name: 'HVAC noise / whoosh', symptom: 'Air noise or fan hum spoils quiet passages.', causes: ['High air velocity at grilles', 'Unlined ducts', 'Fan close to the room or rigidly mounted'], diagnose: ['Measure NC with HVAC on and off'], fixes: ['Bigger grilles/ducts, lower velocity', 'Silencers / baffle boxes', 'Isolate the fan; flexible connectors'], alternatives: ['Switch off for critical takes (plan for it)'], tools: ['calc'] },
  { id: 'hum', name: 'Electrical hum & buzz', symptom: '50/60 Hz hum or buzz in recordings or from the room.', causes: ['Ground loops', 'Dimmers, ballasts, LED drivers', 'Transformers or power supplies in the room'], diagnose: ['Unplug gear one at a time; check lighting'], fixes: ['Balanced connections; single ground point', 'Replace noisy dimmers/drivers', 'Move power supplies out of the room'], alternatives: [], tools: [] },
  { id: 'echo-hall', name: 'Echo in a hall or large room', symptom: 'Distinct repeats of speech or drums from one direction.', causes: ['Rear wall facing the stage', 'Concave surfaces focusing', 'Long delay (> 50 ms) strong reflections'], diagnose: ['Clap and listen for direction', 'Path difference > 17 m = echo risk'], fixes: ['Absorb or diffuse the reflecting wall', 'Tilt surfaces to redirect into audience', 'Break up concave shapes'], alternatives: ['Aim loudspeakers away from the problem surface'], tools: ['absorbers', 'diffusers'] },
  { id: 'speech', name: 'Speech hard to understand', symptom: 'Words smear together; people raise their voices.', causes: ['Long RT', 'High background noise', 'Loudspeakers exciting the reverberant field'], diagnose: ['Estimate RT in the Room Analyzer', 'Measure background noise'], fixes: ['Ceiling absorption', 'Directional loudspeakers', 'Quiet the HVAC'], alternatives: ['Sound masking only in offices'], tools: ['analyzer'] },
  { id: 'rattle', name: 'Rattles & sympathetic buzzes', symptom: 'Things buzz on certain bass notes.', causes: ['Loose panels, light fittings, window sashes, cabinet doors', 'Ducts and drywall resonating'], diagnose: ['Play a slow low-frequency sweep (Calculators → Tone generator) and listen'], fixes: ['Tighten, add damping pads, seal windows, screw panels'], alternatives: [], tools: ['calc'] },
  { id: 'traffic', name: 'Traffic noise through windows', symptom: 'Low rumble of traffic and buses.', causes: ['Thermal double glazing with small gap', 'Leaky frames, trickle vents'], diagnose: ['Is it louder near the window? Light test on seals'], fixes: ['Secondary glazing with a large gap', 'Laminated glass, different thicknesses', 'Seal frames; acoustic trickle vents'], alternatives: ['Window plug when recording'], tools: ['isolation'] },
  { id: 'comb-desk', name: 'Phasey sound at the desk', symptom: 'Tone changes when you lean forward or back.', causes: ['Desk/console reflection comb filtering', 'Monitors too low and aimed across the desk'], diagnose: ['Comb-filter calculator: path difference to notch frequency'], fixes: ['Raise monitors on stands behind the desk; angle down', 'Shorter or sloped desk; absorb in front of desk'], alternatives: [], tools: ['calc'] },
];

